SELECT COUNT(*) AS total_rows, MIN(customer_id) AS first_id, MAX(customer_id) AS last_id FROM DWBI_Bank.dbo.retail_banking_crm;
SELECT COUNT(*) AS total_rows, SUM(CASE WHEN y = 'yes' THEN 1 ELSE 0 END) AS subscriptions FROM DWBI_Bank.stage.marketing_call_center;
SELECT COUNT(*) AS total_rows, COUNT(DISTINCT customer_id) AS unique_ids FROM DWBI_Bank.stage.credit_and_risk;
SELECT COUNT(*) AS total_rows, COUNT(DISTINCT customer_id) AS unique_ids FROM DWBI_Bank.stage.finance_external_feed;
SELECT COUNT(*) AS joined_rows, SUM(CASE WHEN c.customer_id IS NULL THEN 1 ELSE 0 END) AS missing_crm, SUM(CASE WHEN r.customer_id IS NULL THEN 1 ELSE 0 END) AS missing_credit, SUM(CASE WHEN e.customer_id IS NULL THEN 1 ELSE 0 END) AS missing_economic, SUM(CASE WHEN m.y = 'yes' THEN 1 ELSE 0 END) AS subscriptions FROM DWBI_Bank.stage.marketing_call_center AS m LEFT JOIN DWBI_Bank.dbo.retail_banking_crm AS c ON m.customer_id = c.customer_id LEFT JOIN DWBI_Bank.stage.credit_and_risk AS r ON m.customer_id = r.customer_id LEFT JOIN DWBI_Bank.stage.finance_external_feed AS e ON m.customer_id = e.customer_id;